{
  "title": "Kyushu Preparations and the Honshu Decision",
  "setting": "Washington, 18 June 1945, meeting of the President and senior advisers.",
  "decider": "The President",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The President",
  "agent_role": "decide",
  "situation": "The President was considering whether to continue preparations for a Kyushu operation, with the decision on a later Honshu invasion still open. Advisers had presented differing casualty figures, and estimates for an invasion carried substantial uncertainty. Prior operations offered comparisons, but advisers disagreed about whether Kyushu losses would resemble the experience on Luzon or Okinawa. Military planners expected substantial Japanese forces on Kyushu and assessed that reinforcement from the mainland would become increasingly difficult. The President remained concerned about American casualties and the possibility that an invasion of Japan could intensify Japanese resistance. A staged approach that allowed reconsideration after the Kyushu campaign and anticipated Soviet entry was also under consideration.",
  "question": "What should the President do about continued preparations for the Kyushu operation and the timing of the Honshu decision?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The President sought estimates of the time and American losses associated with invasion and with an approach based on isolation, blockade, and bombardment, intending to make the campaign decision with the greatest possible economy of American lives.",
      "spans": [
        "src:8d1aaa543ec2#p13.4"
      ]
    },
    {
      "id": "F2",
      "kind": "assessed",
      "status": "assessed",
      "fact": "The Joint War Plans Committee estimated total American casualties of 132,500 to 220,000 across three invasion scenarios.",
      "spans": [
        "src:8d1aaa543ec2#p14.3",
        "src:8d1aaa543ec2#p14.5",
        "src:8d1aaa543ec2#p14.6",
        "src:8d1aaa543ec2#p14.7"
      ]
    },
    {
      "id": "F3",
      "kind": "assessed",
      "status": "assessed",
      "fact": "The casualty estimates were described as uncertain, with major possible variation based on the level of opposition and the time required for the operation.",
      "spans": [
        "src:8d1aaa543ec2#p14.3"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Joint Planning Staff removed the casualty table and the figure of 766,700 American personnel from the draft sent to the Joint Chiefs, without substituting other figures or descriptive language.",
      "spans": [
        "src:8d1aaa543ec2#p14.9"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Background figures included 34,000 ground and 7,700 Navy American casualties on Okinawa, compared with 81,000 Japanese casualties; the Okinawa figures were not final.",
      "spans": [
        "src:8d1aaa543ec2#p15.6",
        "src:8d1aaa543ec2#p15.7"
      ]
    },
    {
      "id": "F6",
      "kind": "assessed",
      "status": "assessed",
      "fact": "The theater commander's staff projected 50,800 battle casualties in the first 30 days and 105,050 in the first 90 days of the Kyushu operation, plus 12,600 nonbattle casualties; the commander later characterized the figures as cautious logistical planning estimates and gave no explicit estimate of actual losses.",
      "spans": [
        "src:8d1aaa543ec2#p15.8",
        "src:8d1aaa543ec2#p15.10"
      ]
    },
    {
      "id": "F7",
      "kind": "assessed",
      "status": "assessed",
      "fact": "A senior naval adviser argued that Kyushu casualties were more likely to resemble Okinawa's experience and suggested applying Okinawa's 35-percent casualty rate to the 766,700 personnel planned for the operation; the senior Army adviser did not calculate that figure.",
      "spans": [
        "src:8d1aaa543ec2#p16.10"
      ]
    },
    {
      "id": "F8",
      "kind": "intelligence",
      "status": "assessed",
      "fact": "Military planners expected eight Japanese divisions and 350,000 military personnel on Kyushu by November.",
      "spans": [
        "src:8d1aaa543ec2#p17.1"
      ]
    },
    {
      "id": "F9",
      "kind": "intelligence",
      "status": "assessed",
      "fact": "Military advisers assessed that air and naval action would reduce Japanese reinforcement from the mainland to negligible levels by 1 November, while the President asked about possible reinforcement from other Japanese islands.",
      "spans": [
        "src:8d1aaa543ec2#p17.2",
        "src:8d1aaa543ec2#p17.4"
      ]
    },
    {
      "id": "F10",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The President expressed concern that an invasion of Japan could unite the Japanese for a fight to the finish; the plan presented for consideration left the Honshu decision until later, allowing consideration of the Kyushu campaign and anticipated Soviet entry.",
      "spans": [
        "src:8d1aaa543ec2#p17.5",
        "src:8d1aaa543ec2#p17.6"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The President authorizes continued preparations for Kyushu and defers the Honshu decision.",
      "move": "act",
      "disposition": "authorize",
      "irreversible": false
    },
    "O2": {
      "do": "The President declines continued preparations for Kyushu and defers the Honshu decision.",
      "move": "act",
      "disposition": "decline",
      "irreversible": false
    },
    "O3": {
      "do": "The President defers the Kyushu decision and requests revised casualty estimates from military advisers.",
      "move": "ask",
      "disposition": "defer",
      "irreversible": false,
      "to": "military advisers"
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "no_opposite_reason": "",
  "real_option": "O1",
  "authored_options": [
    "O2",
    "O3"
  ]
}

